package com.clinic.notification.controller;
import com.clinic.notification.dto.NotificationDtos.*;import com.clinic.notification.service.NotificationQueueService;import jakarta.validation.Valid;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/notifications") public class NotificationController{private final NotificationQueueService service;private final String key;public NotificationController(NotificationQueueService s,@Value("${app.internal-api-key}")String key){service=s;this.key=key;}
 @PostMapping("/events")@ResponseStatus(HttpStatus.ACCEPTED)void event(@RequestHeader("X-Internal-Key")String p,@Valid@RequestBody EventRequest r){check(p);service.enqueue(r);}@PostMapping("/medication-plans")@ResponseStatus(HttpStatus.ACCEPTED)void plan(@RequestHeader("X-Internal-Key")String p,@Valid@RequestBody MedicationPlanRequest r){check(p);service.addPlan(r);}private void check(String p){if(!key.equals(p))throw new SecurityException("Invalid internal credential");}}
